.meter { display: flex; flex-direction: column; gap: var(--space-1); min-inline-size: 0; }

/* THE TRACK IS A RULE, NOT A TUBE.
 *
 * It was 10px with a hard black tick standing on it, which is the 2014 progress
 * bar (owner, 23.08: this does not look modern). Six pixels reads as a
 * measurement rather than a container, and the marker below says "the goal is
 * here" without stamping on the fill. */
.meter-track {
  position: relative;
  block-size: 6px;
  border-radius: var(--radius-full);
  background: var(--chart-track);
  overflow: visible;
}
.meter[data-size="sm"] .meter-track { block-size: 4px; }

.meter-fill {
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  border-radius: var(--radius-full);
  background: var(--primary);
  /* The reading arrives instead of being there already — one gesture, the same
   * curve every other part of the system answers on. */
  transform-origin: inline-start;
  animation: meter-fill var(--duration-slow) var(--ease-out) both;
}
@keyframes meter-fill {
  from { transform: scaleX(0); }
}
.meter[data-tone="success"] .meter-fill { background: var(--chart-success); }
.meter[data-tone="warning"] .meter-fill { background: var(--chart-warning); }
.meter[data-tone="danger"] .meter-fill { background: var(--chart-danger); }

/* THE GOAL. A hairline standing across the track, ringed in the surface colour
 * so it reads whether it lands on the fill or on the empty part. */
.meter-target {
  position: absolute;
  inset-block: -3px;
  inline-size: 2px;
  border-radius: var(--radius-full);
  background: var(--foreground);
  box-shadow: 0 0 0 2px var(--card);
}

.meter-ticks {
  display: flex; justify-content: space-between;
  font-size: var(--font-xs); color: var(--chart-axis); font-variant-numeric: tabular-nums;
}

import "./Meter.css";
import { cn } from "../lib/cn";

type Tone = "primary" | "success" | "warning" | "danger";
type Size = "sm" | "md";

type Props = {
  value: number;
  /** Scale maximum (default 100). */
  max?: number;
  /** Optional goal marker rendered on the track. */
  target?: number;
  /** What the reading MEANS, and it does not come from the fill: 1.4 of 3 short of target is
   *  `warning`; the same 1.4 against a target of 1 is `success`. Colour picked from the
   *  percentage congratulates you for missing.
   */
  tone?: Tone;
  /** Density, not importance: `md` when the meter is the point of its block, `sm` in a row of
   *  many where the reader scans for the odd one out.
   */
  size?: Size;
  /** Tick labels under the track: an explicit list, or `true` for [0, max]. */
  ticks?: number[] | boolean;
  /** Accessible description of what the meter measures. */
  label?: string;
  className?: string;
};

const clamp = (n: number) => Math.max(0, Math.min(100, n));

/** A linear progress / gauge on a fixed scale, with an optional target marker.
 *  The fill width and marker position are the only dynamic inline styles. 
 *
 * Copy: the label carries the sentence, because a gauge with a number and no
 * subject is a decoration: "Storage used, 62 of 100 GB".
 */
export function Meter({ value, max = 100, target, tone = "primary", size, ticks, label, className }: Props) {
  const pct = clamp((value / max) * 100);
  const targetPct = target != null ? clamp((target / max) * 100) : null;
  const tickVals = Array.isArray(ticks) ? ticks : ticks ? [0, max] : null;

  return (
    <div
      className={cn("meter", className)}
      data-tone={tone}
      data-size={size}
      role="meter"
      aria-valuenow={value}
      aria-valuemin={0}
      aria-valuemax={max}
      aria-label={label}
    >
      <div className="meter-track">
        <div className="meter-fill" style={{ inlineSize: `${pct}%` }} />
        {targetPct != null && (
          <div className="meter-target" style={{ insetInlineStart: `${targetPct}%` }} aria-hidden="true" />
        )}
      </div>
      {tickVals && (
        <div className="meter-ticks">
          {tickVals.map((t) => (
            <span key={t}>{t}</span>
          ))}
        </div>
      )}
    </div>
  );
}
